// Root original complete surface observations and direct actual-body witnesses.
use mermaid_rs_renderer::scene::prepare::blitter::surface_types::{BorrowedPixmapMut,OwnedMask,LogicalTarget};
use tiny_skia_path::{IntSize,IntRect};use serde::Deserialize;use std::panic::AssertUnwindSafe;
#[derive(Deserialize)]struct OwnershipInput{data:Vec<u8>,capacity:usize,width:u32,height:u32}#[derive(Deserialize)]struct OwnershipCase{input:OwnershipInput,result:(String,bool,usize,usize)}#[derive(Deserialize)]struct OwnershipFixture{cases:Vec<OwnershipCase>}
#[test]fn original_owned_mask_allocation_identity(){let f:OwnershipFixture=serde_json::from_str(include_str!("fixtures/borrowed-ownership.json")).unwrap();assert_eq!(f.cases.len(),80);let mut mismatches=0;for c in f.cases{let i=c.input;let mut data=Vec::with_capacity(i.capacity);data.extend_from_slice(&i.data);let ptr=data.as_ptr();let before=data.capacity();let result=if let Some(size)=IntSize::from_wh(i.width,i.height){match OwnedMask::from_vec(data,size){Some(mask)=>("some".into(),mask.data.as_ptr()==ptr,before,mask.data.capacity()),None=>("none".into(),false,before,0)}}else{("none".into(),false,before,0)};mismatches+=usize::from(result!=c.result);}println!("80 actual original owned mask allocation records / {mismatches} mismatches");assert_eq!(mismatches,0);}
#[derive(Debug,Deserialize)]struct Input{kind:u8,width:u32,height:u32,data:Vec<u8>,rect:Option<[i32;4]>,write:Option<(usize,u8)>}
type View=(u32,u32,usize,usize,usize,Vec<u8>,Vec<u8>);type Record=(String,Option<View>,Vec<u8>);
#[derive(Deserialize)]struct Case{input:Input,result:Record}#[derive(Deserialize)]struct Fixture{cases:Vec<Case>}
fn count_stub(e:&(dyn std::any::Any+Send),stubs:&mut usize){let s=e.downcast_ref::<&str>().copied().or_else(||e.downcast_ref::<String>().map(String::as_str)).unwrap_or("");if s.contains("Unimplemented Root-frozen"){*stubs+=1;}}
fn capture(v:LogicalTarget<'_>,base:usize,write:Option<(usize,u8)>)->View{let offset=v.data.as_ptr() as usize-base;let before=v.data.to_vec();if let Some((i,b))=write{if let Some(byte)=v.data.get_mut(i){*byte=b;}}(v.size.width(),v.size.height(),v.real_width,offset,v.data.len(),before,v.data.to_vec())}
fn observe(i:&Input)->Record{
 let mut data=i.data.clone();let mut record=None;let mut status="some";
 if i.kind==0{let base=data.as_ptr() as usize;if let Some(mut p)=BorrowedPixmapMut::from_bytes(&mut data,i.width,i.height){if let Some(r)=i.rect{if let Some(r)=IntRect::from_xywh(r[0],r[1],r[2] as u32,r[3] as u32){if let Some(v)=p.subpixmap(r){record=Some(capture(v,base,i.write));}else{status="rect-none";}}else{status="rect-none";}}else{record=Some(capture(p.as_subpixmap(),base,i.write));}}else{status="ctor-none";}}
 else{if let Some(size)=IntSize::from_wh(i.width,i.height){if let Some(mut m)=OwnedMask::from_vec(data.clone(),size){let base=m.data.as_ptr() as usize;let rect=i.rect.and_then(|r|IntRect::from_xywh(r[0],r[1],r[2] as u32,r[3] as u32));if i.rect.is_some()&&rect.is_none(){status="rect-none";}else if i.kind==2{let view=if let Some(r)=rect{m.subpixmap(r)}else{Some(m.as_subpixmap())};if let Some(v)=view{record=Some(capture(v,base,i.write));}else{status="rect-none";}}else{let view=if let Some(r)=rect{m.submask(r)}else{Some(m.as_submask())};if let Some(v)=view{record=Some((v.size.width(),v.size.height(),v.real_width as usize,v.data.as_ptr() as usize-base,v.data.len(),v.data.to_vec(),v.data.to_vec()));}else{status="rect-none";}}data=m.data;}else{status="ctor-none";}}else{status="ctor-none";}}
 (status.into(),record,data)
}
#[test]fn actual_original_borrowed_surface_records(){let hook=std::panic::take_hook();std::panic::set_hook(Box::new(|_|{}));let f:Fixture=serde_json::from_str(include_str!("fixtures/borrowed-surfaces.json")).unwrap();assert_eq!(f.cases.len(),3240);let(mut mismatches,mut stubs,mut errors)=(0,0,0);let mut first=vec![];for(index,c)in f.cases.iter().enumerate(){let result=std::panic::catch_unwind(||observe(&c.input));if let Err(e)=&result{count_stub(&**e,&mut stubs);errors+=1;}let actual=result.ok();if actual.as_ref()!=Some(&c.result){mismatches+=1;if first.len()<3{first.push(format!("case {index} input={:?} actual={actual:?} Source={:?}",c.input,c.result));}}}std::panic::set_hook(hook);println!("3240 actual original borrowed surface records / {mismatches} mismatches / {stubs} actual stub calls / {errors} errors");assert_eq!(mismatches,0,"{}",first.join("\n"));assert_eq!(stubs,0);assert_eq!(errors,0);}
#[test]fn all_eight_surface_methods_are_implemented(){let hook=std::panic::take_hook();std::panic::set_hook(Box::new(|_|{}));let mut stubs=0;let size=IntSize::from_wh(2,2).unwrap();let rect=IntRect::from_xywh(1,1,1,1).unwrap();for method in 0..8{let mut rgba=[0;16];let mut p=BorrowedPixmapMut{data:&mut rgba,size};let mut m=OwnedMask{data:vec![0;4],size};let result=std::panic::catch_unwind(AssertUnwindSafe(||match method{0=>{let _=BorrowedPixmapMut::from_bytes(&mut [0;16],2,2);},1=>{let _=p.as_subpixmap();},2=>{let _=p.subpixmap(rect);},3=>{let _=OwnedMask::from_vec(vec![0;4],size);},4=>{let _=m.as_submask();},5=>{let _=m.submask(rect);},6=>{let _=m.as_subpixmap();},_=>{let _=m.subpixmap(rect);}}));if let Err(e)=result{count_stub(&*e,&mut stubs);}}std::panic::set_hook(hook);println!("Eight direct surface dependency witnesses / {stubs} actual stub calls");assert_eq!(stubs,0);}
